// === Tab: Tower ===
class Tower {
	constructor(x, y, alpha) {
		this.pos = createVector(x, y);
		this.v = createVector(0, -1).setMag(random(1, 5));
		this.size = random(50, 80)
		this.rotation = 0
		this.a = random(-0.1, 0.1)
		this.dead = false;
		this.sat = 90
		// this.color1 = int(random(250, 300))
		// this.color2 = int(random(150, 200))
		this.color1 = color(random(['#212529', '#343A40', '#495057']))
		this.color2 = color(random(['#F8F9FA', '#DEE2E6', '#ADB5BD']))
		this.gridSize = random(2, 6)
		this.alpha = alpha
		this.isCircleTower = random() < 0.1 ? true : false;
	}

	draw() {
		push()
		fill(this.color, this.sat, 100)
		translate(this.pos.x, this.pos.y)
		rotate(this.rotation)
		// filter(BLUR,2)
		// noFill()
		// const clr1 = color(this.color1, this.sat, 90)
		// const clr2 = color(this.color2, this.sat, 90)
		this.color1.setAlpha(this.alpha)
		this.color2.setAlpha(this.alpha)
		patternColors([this.color1, this.color2])
		pattern(PTN.cross(this.gridSize, this.gridSize / 2))
		if (this.isCircleTower) {
			circlePattern(0, 0, this.size * random(), this.size * random())
		} else {
			rectPattern(0, 0, this.size * random(), this.size * random())
		}

		// rectPattern(0, 0, this.size, this.size)
		// rect(0, 0, this.size, this.size)
		pop()
	}

	update() {
		if (this.size > 10) {
			this.pos.add(this.v)
			this.size -= this.size * 0.01
			this.rotation += this.a
			this.sat -= 0.5
		} else {
			this.dead = true;
		}
	}
}

